import { readFile, writeFile } from "node:fs/promises";
await writeFile(
  "supabase/functions/_shared/contracts.ts",
  "// Generated by npm run contracts. Edit shared/contracts.ts instead.\n" +
    (await readFile("shared/contracts.ts", "utf8")),
);
await writeFile(
  "supabase/functions/_shared/missions.ts",
  "// Generated by npm run contracts.\nexport default " +
    (await readFile("shared/missions.json", "utf8")) +
    ";\n",
);
